Profit = 89.75 - 60.25 = 29.5; Profit % = 29.5 / 60.25 * 100 = 48.96265560165975 (about 48.96%).
Output: Profit in per cent = 48.96265560165975%

class Profit
{
    public static void main(String args[])
    {
        double cp = 60.25, sp = 89.75;   // cost price and selling price
        double pr = sp - cp;             // profit
        double percentProfit = pr / cp * 100;
        System.out.println("Profit in per cent = " + percentProfit + "%");
    }
}

/* Variable description
   cp            : double : cost price
   sp            : double : selling price
   pr            : double : profit = sp - cp
   percentProfit : double : profit percentage */

Sample run: 5 and 50 -> Real quotient = 0.1, Remainder = 5.
The cast (double) must be applied to an operand before the division; (double)(num1 / num2) would give 0.0.

import java.util.*;

class Real
{
    public static void main(String args[])
    {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter the first integer (dividend): ");
        int num1 = sc.nextInt();
        System.out.print("Enter the second integer (divisor): ");
        int num2 = sc.nextInt();
        double q = (double) num1 / num2;   // real quotient (cast before dividing)
        int rem = num1 % num2;             // remainder
        System.out.println("Real quotient = " + q);
        System.out.println("Remainder = " + rem);
    }
}

/* Variable description
   num1 : int    : dividend
   num2 : int    : divisor
   q    : double : real (decimal) quotient
   rem  : int    : remainder */

