With t1 = 10:40:35 and t2 = 6:45:29 the output is: 17 : 26 : 4
(seconds 35+29 = 64 -> 4 s, carry 1 min; minutes 40+45+1 = 86 -> 26 min, carry 1 h; hours 10+6+1 = 17.)

class Time
{
    int hours, minutes, seconds;     // instance variables

    public static void main(String args[])
    {
        Time t1 = new Time();
        Time t2 = new Time();
        t1.hours = 10; t1.minutes = 40; t1.seconds = 35;
        t2.hours = 6;  t2.minutes = 45; t2.seconds = 29;

        int s = t1.seconds + t2.seconds;
        int totSeconds = s % 60;
        int m = t1.minutes + t2.minutes + s / 60;    // add carried minutes
        int totMinutes = m % 60;
        int totHours = t1.hours + t2.hours + m / 60; // add carried hours

        System.out.println(totHours + " : " + totMinutes + " : " + totSeconds);
    }
}

/* Variable description
   hours, minutes, seconds : int : instance variables of a Time object
   t1, t2                  : Time : the two time objects
   s, m                    : int : raw sums of seconds and minutes
   totHours, totMinutes, totSeconds : int : the total time */

With T1 = 5:35:20 and T2 = 12:45:35 the output is:
Difference in time is:
7 hours:10 minutes:15 seconds
(T1 = 20120 s, T2 = 45935 s, difference = 25815 s = 7 h, 615 s left = 10 min 15 s.)

class Time
{
    int hours, minutes, seconds;

    public static void main(String args[])
    {
        Time T1 = new Time();
        Time T2 = new Time();
        T1.hours = 5;  T1.minutes = 35; T1.seconds = 20;
        T2.hours = 12; T2.minutes = 45; T2.seconds = 35;

        int totSeconds1 = T1.hours * 3600 + T1.minutes * 60 + T1.seconds;
        int totSeconds2 = T2.hours * 3600 + T2.minutes * 60 + T2.seconds;
        int diff = totSeconds2 - totSeconds1;

        int hr = diff / 3600;
        int left = diff % 3600;
        int min = left / 60;
        int sec = left % 60;

        System.out.println("Difference in time is:");
        System.out.println(hr + " hours:" + min + " minutes:" + sec + " seconds");
    }
}

/* Variable description
   T1, T2                   : Time : the two time objects
   totSeconds1, totSeconds2 : int  : each time converted to seconds
   diff                     : int  : difference in seconds
   hr, min, sec             : int  : difference split into hours, minutes, seconds
   left                     : int  : seconds remaining after whole hours */

With radii 7.0 and 10.0:
Circle 1: Area : 153.86, Circumference : 43.96
Circle 2: Area : 314.0, Circumference : 62.8 (Java may print 62.800000000000004 because of floating-point rounding)

class Circle
{
    double radius;     // instance variable

    public static void main(String args[])
    {
        Circle c1 = new Circle();
        Circle c2 = new Circle();
        c1.radius = 7.0;
        c2.radius = 10.0;

        double area1 = 3.14 * c1.radius * c1.radius;
        double circumference1 = 2 * 3.14 * c1.radius;
        double area2 = 3.14 * c2.radius * c2.radius;
        double circumference2 = 2 * 3.14 * c2.radius;

        System.out.println("Circle 1:");
        System.out.println("Area : " + area1 + ", Circumference : " + circumference1);
        System.out.println("Circle 2:");
        System.out.println("Area : " + area2 + ", Circumference : " + circumference2);
    }
}

/* Variable description
   radius                         : double : radius of a circle object
   c1, c2                         : Circle : the two circle objects
   area1, area2                   : double : areas
   circumference1, circumference2 : double : circumferences */

