With d1 = 5' 9" and d2 = 6' 11" the output is: Total Distance : 12' 8"
(inches 9+11 = 20 -> 8 in, carry 1 ft; feet 5+6+1 = 12.)

class Distance
{
    int feet, inches;     // instance variables

    public static void main(String args[])
    {
        Distance d1 = new Distance();
        Distance d2 = new Distance();
        d1.feet = 5; d1.inches = 9;
        d2.feet = 6; d2.inches = 11;

        int sumIn = d1.inches + d2.inches;
        int totInches = sumIn % 12;
        int totFeet = d1.feet + d2.feet + sumIn / 12;   // 12 inches = 1 foot

        System.out.println("Total Distance : " + totFeet + "' " + totInches + "\"");
    }
}

/* Variable description
   feet, inches       : int : instance variables of a Distance object
   d1, d2             : Distance : the two distance objects
   sumIn              : int : sum of the inches
   totFeet, totInches : int : total distance */

With d1 = 2:50:40 and d2 = 1:45:35 the output is: Total Duration : 04:36:15
(seconds 40+35 = 75 -> 15 s, carry 1; minutes 50+45+1 = 96 -> 36 min, carry 1; hours 2+1+1 = 4.)

class Duration
{
    int hours, minutes, seconds;     // instance variables

    public static void main(String args[])
    {
        Duration d1 = new Duration();
        Duration d2 = new Duration();
        d1.hours = 2; d1.minutes = 50; d1.seconds = 40;
        d2.hours = 1; d2.minutes = 45; d2.seconds = 35;

        int s = d1.seconds + d2.seconds;
        int totS = s % 60;
        int m = d1.minutes + d2.minutes + s / 60;
        int totM = m % 60;
        int totH = d1.hours + d2.hours + m / 60;

        // print each part with two digits (hh:mm:ss)
        String hh = (totH < 10 ? "0" : "") + totH;
        String mm = (totM < 10 ? "0" : "") + totM;
        String ss = (totS < 10 ? "0" : "") + totS;
        System.out.println("Total Duration : " + hh + ":" + mm + ":" + ss);
    }
}

/* Variable description
   hours, minutes, seconds : int : instance variables of a Duration object
   d1, d2                  : Duration : the two duration objects
   s, m                    : int : raw sums of seconds and minutes
   totH, totM, totS        : int : total hours, minutes, seconds
   hh, mm, ss              : String : two-digit forms for printing */

Sample run: 7 and 20 -> Remainder = 7 (7 % 20), Absolute Difference = 13 (Math.abs(7 - 20)).

import java.util.*;

class RemainderAbsDiff
{
    public static void main(String args[])
    {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter the first integer: ");
        int num1 = sc.nextInt();
        System.out.print("Enter the second integer: ");
        int num2 = sc.nextInt();
        int remainder = num1 % num2;
        int absDiff = Math.abs(num1 - num2);
        System.out.println("Remainder = " + remainder);
        System.out.println("Absolute Difference = " + absDiff);
    }
}

/* Variable description
   num1, num2 : int : the two numbers entered
   remainder  : int : num1 % num2
   absDiff    : int : |num1 - num2| using Math.abs() */
